task.vi:
Xác định tất cả các vấn đề và lỗi sai trong đoạn mã định nghĩa hai lớp Circle và B sau:

```cpp
class Circle {
public:
  Circle(double radius) {
    radius = radius;
  }
  double getRadius() { return radius; }
  double getArea() { return radius * radius * 3.14159; }
private:
  double radius;
};

class B: Circle {
public:
  B(double radius, double length) {
    radius = radius;
    length = length;
  }
  double getArea() {
    return getArea() * length;
  }
private:
  double length;
};
```

