#include <iostream>
#include <string>

class Shape {
private:
    std::string color;
    bool filled;
public:
    Shape(const std::string& color = "white", bool filled = false)
        : color(color), filled(filled) {}

    std::string getColor() const { return color; }
    void setColor(const std::string& c) { color = c; }
    bool isFilled() const { return filled; }
    void setFilled(bool f) { filled = f; }
};

class Circle : public Shape {
private:
    double radius;
public:
    Circle(double r, const std::string& c, bool f)
        : Shape(c, f), radius(r > 0 ? r : 0) {}

    double getRadius() const { return radius; }
    double getArea() const { return 3.141592653589793 * radius * radius; }
};

void displayShapeInfo(const Shape& s) {
    std::cout << "Shape color: " << s.getColor()
              << ", filled: " << (s.isFilled() ? "true" : "false") << "\n";
}

int main() {
    Shape genericShape("red", true);
    Circle circle(4.5, "blue", false);

    displayShapeInfo(genericShape);
    displayShapeInfo(circle); // Circle substitutes Shape seamlessly

    return 0;
}

